describe('Order Summary Before Payment Confirmation', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display order summary with correct details before payment confirmation', () => {
    // Intercept the API call to get order details
    cy.intercept('GET', '/api/orders/12345').as('getOrderDetails');

    // Navigate to checkout page
    cy.get('[data-testid="checkout-button"]').click();

    // Wait for order details to load
    cy.wait('@getOrderDetails');

    // Verify order summary is visible
    cy.get('[data-testid="order-summary"]').should('be.visible');

    // Verify order summary contains correct order details
    cy.get('[data-testid="order-summary"]').should('contain', 'Order ID: 12345');
    cy.get('[data-testid="order-summary"]').should('contain', 'Total: $150.00');
    cy.get('[data-testid="order-summary"]').should('contain', 'Shipping: $10.00');
    cy.get('[data-testid="order-summary"]').should('contain', 'Tax: $15.00');
    cy.get('[data-testid="order-summary"]').should('contain', 'Subtotal: $135.00');
    cy.get('[data-testid="order-summary"]').should('contain', 'Discount: $0.00');
    cy.get('[data-testid="order-summary"]').should('contain', 'Grand Total: $150.00');

    // Verify payment options are displayed
    cy.get('[data-testid="payment-methods"]').should('be.visible');
    cy.get('[data-testid="payment-method-card"]').should('be.visible');
    cy.get('[data-testid="payment-method-paypal"]').should('be.visible');

    // Verify confirm button is visible
    cy.get('[data-testid="confirm-payment-button"]').should('be.visible');
  });

  it('should handle empty order summary when no order details are available', () => {
    // Intercept the API call to get order details
    cy.intercept('GET', '/api/orders/99999').as('getOrderDetails');

    // Navigate to checkout page
    cy.get('[data-testid="checkout-button"]').click();

    // Wait for order details to load
    cy.wait('@getOrderDetails');

    // Verify order summary is not visible when no order details are returned
    cy.get('[data-testid="order-summary"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'No order details found');

    // Verify user is redirected to error page
    cy.url().should('include', '/error');
  });
});
